class Solution:
    def maxItems(self, items: list[list[int]], budget: int) -> int:
        n = len(items)
        mn = min(p for _, p in items)
        best = 0
        for mask in range(1 << n):
            cost = 0
            fs = []
            for i in range(n):
                if mask >> i & 1:
                    cost += items[i][1]
                    fs.append(items[i][0])
            if cost > budget:
                continue
            purchased = bin(mask).count("1") + (budget - cost) // mn
            cnt = {}
            for f in fs:
                cnt[f] = cnt.get(f, 0) + 1
            edges = 0
            for f in cnt:
                for g in cnt:
                    if g != f and g % f == 0:
                        edges += 1
            best = max(best, purchased + min(edges, purchased))
        return best

