class Solution {
public:
    int maxItems(vector<vector<int>>& items, int budget) {
        int n = items.size();
        long long mn = LLONG_MAX;
        for (auto& it : items) mn = min(mn, (long long)it[1]);
        long long best = 0;
        for (int mask = 0; mask < (1 << n); mask++) {
            long long cost = 0;
            vector<int> fs;
            for (int i = 0; i < n; i++)
                if (mask >> i & 1) { cost += items[i][1]; fs.push_back(items[i][0]); }
            if (cost > budget) continue;
            long long purchased = __builtin_popcount(mask) + (budget - cost) / mn;
            unordered_map<int,int> cnt;
            for (int f : fs) cnt[f]++;
            long long edges = 0;
            for (auto& a : cnt)
                for (auto& b : cnt)
                    if (a.first != b.first && b.first % a.first == 0) edges++;
            best = max(best, purchased + min(edges, purchased));
        }
        return (int)best;
    }
};

