class Solution {
    public int maxItems(int[][] items, int budget) {
        int n = items.length;
        long mn = Long.MAX_VALUE;
        for (int[] it : items) mn = Math.min(mn, it[1]);
        long best = 0;
        for (int mask = 0; mask < (1 << n); mask++) {
            long cost = 0;
            List<Integer> fs = new ArrayList<>();
            for (int i = 0; i < n; i++)
                if ((mask >> i & 1) == 1) { cost += items[i][1]; fs.add(items[i][0]); }
            if (cost > budget) continue;
            long purchased = Integer.bitCount(mask) + (budget - cost) / mn;
            Map<Integer,Integer> cnt = new HashMap<>();
            for (int f : fs) cnt.merge(f, 1, Integer::sum);
            long edges = 0;
            for (int f : cnt.keySet())
                for (int g : cnt.keySet())
                    if (g != f && g % f == 0) edges++;
            best = Math.max(best, purchased + Math.min(edges, purchased));
        }
        return (int) best;
    }
}

