class Solution:
    def maxItems(self, items: list[list[int]], budget: int) -> int:
        items.sort(key=lambda x: x[1])
        n = len(items)
        spent = 0
        bought = []
        for f, p in items:
            if spent + p <= budget:
                spent += p
                bought.append(f)
        purchased = len(bought) + (budget - spent) // items[0][1]
        cnt = [0] * (n + 1)
        for f in bought:
            cnt[f] += 1
        edges = 0
        for f in set(bought):
            for m in range(f, n + 1, f):
                edges += cnt[m]
            edges -= 1
        return purchased + min(edges, purchased)

