class Solution {
public:
    int maxItems(vector<vector<int>>& items, int budget) {
        sort(items.begin(), items.end(), [](auto& a, auto& b){ return a[1] < b[1]; });
        int n = items.size();
        long long spent = 0;
        vector<int> bought;
        for (auto& it : items) {
            if (spent + it[1] <= budget) { spent += it[1]; bought.push_back(it[0]); }
        }
        long long purchased = bought.size() + (budget - spent) / items[0][1];
        vector<int> cnt(n + 1, 0);
        for (int f : bought) cnt[f]++;
        long long edges = 0;
        for (int f : unordered_set<int>(bought.begin(), bought.end())) {
            for (int m = f; m <= n; m += f) edges += cnt[m];
            edges -= 1;
        }
        return (int)(purchased + min(edges, purchased));
    }
};

