class Solution {
    public int maxItems(int[][] items, int budget) {
        Arrays.sort(items, (a, b) -> Integer.compare(a[1], b[1]));
        int n = items.length;
        long spent = 0;
        List<Integer> bought = new ArrayList<>();
        for (int[] it : items) {
            if (spent + it[1] <= budget) { spent += it[1]; bought.add(it[0]); }
        }
        long purchased = bought.size() + (budget - spent) / items[0][1];
        int[] cnt = new int[n + 1];
        for (int f : bought) cnt[f]++;
        Set<Integer> seen = new HashSet<>(bought);
        long edges = 0;
        for (int f : seen) {
            for (int m = f; m <= n; m += f) edges += cnt[m];
            edges -= 1;
        }
        return (int) (purchased + Math.min(edges, purchased));
    }
}

